Below are compact examples illustrating client-side handling patterns.

Python (requests-like pseudo):

```python
from time import sleep

MAX_ATTEMPTS = 3

def call_with_error_model(req):
    attempt = 0
    while True:
        attempt += 1
        resp = client.send(req)  # raises SDKError or returns response
        if resp.ok:
            return resp.value
        err = resp.error
        # non-retryable -> bubble up immediately
        if not err.get('retryable'):
            raise err
        # obey server-suggested retry-after when present
        ra = err.get('retry_after_seconds')
        if ra:
            sleep(ra)
        else:
            # limited attempt count
            if attempt > err.get('safe_retries', MAX_ATTEMPTS):
                # escalate or try fallback
                if err.get('fallback'):
                    return try_fallback(req, err['fallback'])
                raise err
            # basic exponential backoff with jitter
            sleep(min(2 ** attempt * 0.1, 5.0) * (0.8 + 0.4 * random()))

```

Node.js (async pattern):

```javascript
async function callWithErrorModel(req) {
  let attempt = 0
  while (true) {
    attempt += 1
    const { ok, value, error } = await client.send(req)
    if (ok) return value
    if (!error.retryable) throw error
    if (error.retry_after_seconds) await sleep(error.retry_after_seconds * 1000)
    else {
      if (attempt > (error.safe_retries || 3)) {
        if (error.fallback) return tryFallback(req, error.fallback)
        throw error
      }
      await sleep(Math.min(2 ** attempt * 100, 5000) * (0.8 + Math.random() * 0.4))
    }
  }
}
```
